const D = { sheen: .6, scale: 1, energy: .6, density: .5, hue: 34, speed: 1, x: .5, y: .42, alpha: 1, style: 'wet', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const shn=cl(P.sheen,0,1), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=Math.max(360,Math.min(720,Math.round(W/2.4))), BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,720);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; }
const G=S.g;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let rate, wetM;
if(act==='haul'){ rate=3.4; wetM=1; }
else if(act==='stall'){ rate=.30; wetM=1.25; }
else { rate=1; wetM=1; }
wetM*=(.85+.30*Math.sin(sec*.9+T*.017));

// ---- the road runs toward the viewer. A monotonic scroll: it never comes back, so the
// motion floor cannot re-phase away over any 8s window.
const scroll=.62*TD*rate;
// street lamps standing off down the road — on a wet plane each throws a long streak
const NLM=3;
const lampX=[], lampA=[];
for(let k=0;k<NLM;k++){
  lampX.push((fr(k*5.1+300)-.5)*2.4 + .30*Math.sin(TD*(.021+.013*k)+k*2.1));
  lampA.push(.55+.45*fr(k*5.1+301));
}

// ---- style ----
let TAR, CHIP, PAINT, LAMP, contour=0, sodium=0, dryK=1;
if(sty==='dry'){ TAR=hsb2rgb(H+186,7,26); CHIP=hsb2rgb(H+16,9,52); PAINT=hsb2rgb(H+14,10,80); LAMP=[255,238,196]; dryK=.18; }
else if(sty==='worn'){ TAR=hsb2rgb(H+184,9,22); CHIP=hsb2rgb(H+12,12,46); PAINT=hsb2rgb(H+18,16,58); LAMP=[255,236,190]; dryK=.55; }
else if(sty==='sodium'){ TAR=hsb2rgb(H-6,34,14); CHIP=hsb2rgb(H-2,30,34); PAINT=hsb2rgb(H+2,26,58); LAMP=[255,196,96]; }
else if(sty==='contour'){ TAR=hsb2rgb(H+190,26,13); CHIP=hsb2rgb(H+180,10,72); PAINT=hsb2rgb(H+170,8,94); LAMP=[190,240,255]; contour=1; }
else { TAR=hsb2rgb(H+188,10,17); CHIP=hsb2rgb(H+14,10,40); PAINT=hsb2rgb(H+16,12,74); LAMP=[255,240,204]; }

// ---- the plane ----
const hz=cl(P.y,.22,.76)*Hh, gH=Math.max(24,Hh-hz);
const vpx=cl(P.x,.05,.95)*W;
const chipF=(58+dens*70)/Math.max(.35,sc);
const f1=chipF*.0700, f2=chipF*.0193, f3=chipF*.1117;   // irrational-ish ratios
const laneW=1.05*sc, trackX=.52*sc;
const wet=shn*wetM;
const glow=(.4+.9*en)*(.55+.7*K.intensity)+S.tre*.3*en;

G.loadPixels();
const px=G.pixels;
for(let j=0;j<BH;j++){
  const sy=(j/BH)*Hh;
  const o0=j*BW*4;
  if(sy<=hz+.5){ for(let i=0;i<BW;i++) px[o0+i*4+3]=0; continue; }   // above the horizon: nothing
  // perspective: t=0 at the horizon, 1 at the near edge
  const t=cl((sy-hz)/gH,0.0001,1);
  const persp=1/(t*t*1.55+.105);             // world depth for this row
  const lodMix=cl(1.25/(1+persp*.42),0,1);   // fine grain dies off with distance
  const rowW=(W*.5)/(persp*.30+.30);         // world->screen x scale for this row
  const wz=persp*.90+scroll;
  const fade=cl(1-Math.pow(1-t,2.4)*1.05,0,1);   // haze into the distance
  for(let i=0;i<BW;i++){
    const sx=(i/BW)*W;
    const wx=((sx-vpx)/Math.max(1e-4,rowW))*2.6/sc;
    const o=o0+i*4;
    // aggregate: chips of stone set in bitumen — the tar is never a flat fill
    const a1=nzAt(wx*f1+11.1, wz*f1+3.3);
    const a2=nzAt(wx*f2-5.5, wz*f2+8.8);
    const a3=nzAt(wx*f3+2.7, wz*f3+19.4);
    let chip=cl((a1*.50+a2*.42+a3*.38-.55)*3.6,0,1);
    chip=(.5+(chip-.5)*lodMix)*(.5+.5*fade);
    // tyre polish: two tracks worn smoother and darker than the lane between them
    const tr=Math.exp(-Math.pow((Math.abs(wx)-trackX)/(.30*sc),2));
    // the crack net, and patched repairs
    const c1=nzAt(wx*.42+21.1, wz*.42+13.7), c2=nzAt(wx*1.15-3.3, wz*1.15+7.7);
    const rid=1-Math.abs((c1*.7+c2*.3)-.5)*2.55;
    const crack=cl(rid*(1.15-.5*tr),0,1);
    const crackD=Math.pow(crack,2.2)*(sty==='worn'?1:.55)*(.35+.6*dens);
    let R,Gc,B;
    // bitumen + aggregate, tracks polished dark
    const cm=chip*(1-tr*.45)*(sty==='worn'?1.15:1);
    R=TAR[0]+(CHIP[0]-TAR[0])*cm; Gc=TAR[1]+(CHIP[1]-TAR[1])*cm; B=TAR[2]+(CHIP[2]-TAR[2])*cm;
    R*=(1-tr*.16); Gc*=(1-tr*.16); B*=(1-tr*.16);
    R*=(1-crackD*.62); Gc*=(1-crackD*.62); B*=(1-crackD*.62);
    // lane markings: a dashed centre line and solid edges, scrolling toward the viewer
    const dash=md(wz*.22,1)<(.52-.12*dens)?1:0;
    const cline=Math.exp(-Math.pow(wx/(.115*sc),2))*dash;
    const eline=Math.exp(-Math.pow((Math.abs(wx)-laneW)/(.100*sc),2));
    const paint=cl(cline+eline,0,1)*(sty==='worn'?.55:1)*(1-crackD*.5);
    R=R+(PAINT[0]-R)*paint*.92; Gc=Gc+(PAINT[1]-Gc)*paint*.92; B=B+(PAINT[2]-B)*paint*.92;
    // wet film: a standing water sheet in the low spots, mirroring the lamps down the road
    if(wet>.02){
      const pd=nzAt(wx*.30+41.1, wz*.30+17.3);
      const pool=cl((pd-.50)*2.6,0,1);
      const film=cl(wet*(.42+.75*pool),0,1.25);
      // a wet plane darkens and saturates before it ever reflects anything
      R*=(1-film*.50); Gc*=(1-film*.50); B*=(1-film*.46);
      let st=0;
      for(let k=0;k<NLM;k++){
        // the reflection smears ALONG the view direction and stays narrow across it —
        // this is why wet tarmac throws long vertical streaks, not round blobs
        const wid=(.045+.30*(1-t))*sc*(1+(1-wet)*2.6);
        const d=(wx-lampX[k])/wid;
        st+=lampA[k]*Math.exp(-d*d)*(.30+.9*t)*(.35+1.15*wet);
      }
      // ripple the film so the streak breaks up rather than reading as a clean mirror
      const rip=1+.55*(nzAt(wx*2.1+7.7, wz*.55-scroll*.35+2.2)-.5);
      const sp=cl(st*film*glow*rip*(.35+.9*fade),0,3.2)*78;
      R+=LAMP[0]*sp/255; Gc+=LAMP[1]*sp/255; B+=LAMP[2]*sp/255;
    }
    if(contour){
      // non-representational: a pavement survey — the surface as pure elevation contours
      const h=(a1*.45+a2*.42+a3*.38)*1.5+crack*.35-tr*.25;
      const band=Math.abs(md(h*13,1)-.5)*2;
      const li=Math.pow(cl(1-band*1.35,0,1),1.5);
      const v=.13+.16*chip+.85*li*fade;
      R=TAR[0]*(1-li*.8)+CHIP[0]*v; Gc=TAR[1]*(1-li*.8)+CHIP[1]*v; B=TAR[2]*(1-li*.8)+CHIP[2]*v;
      R+=PAINT[0]*paint*.5; Gc+=PAINT[1]*paint*.5; B+=PAINT[2]*paint*.5;
    }
    // haze the far road into the horizon so the plane really recedes
    const hf=1-fade;
    R=R*(1-hf*.72)+TAR[0]*1.9*hf*.72; Gc=Gc*(1-hf*.72)+TAR[1]*1.9*hf*.72; B=B*(1-hf*.72)+TAR[2]*2.2*hf*.72;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
